// === FLATTEN METRICS FOR SUPABASE ===
// The Sheets node this replaces was named 'Append Row' but had no `operation`
// set, and the v4 default is READ — so it read a sheet every weekday for ~125
// runs and wrote nothing. The tracker had a header row and zero data rows.
//
// Metrics live nested under $json.metrics; Postgres wants flat, typed columns
// so the series can be aggregated (trend the free hours, the overdue count,
// the goal percentage). One row per brief_date, upserted — a re-run corrects
// the day rather than duplicating it.
const j = $json;
const m = j.metrics || {};
const num = (v) => (typeof v === 'number' && isFinite(v)) ? v : null;

return [{ json: {
  brief_date:            j.date,
  day_of_week:           j.dayOfWeek || null,
  meeting_count:         num(m.meetingCount),
  meeting_hours:         num(m.meetingHours),
  free_hours:            num(m.freeHours),
  largest_free_block_min: num(m.largestFreeBlockMin),
  task_total:            num(m.totalTaskCount),
  task_overdue:          num(m.overdueTaskCount),
  email_total:           num(m.totalEmailCount),
  email_needs_reply:     num(m.needsReplyCount),
  email_old:             num(m.oldEmailCount),
  weekly_goal_pct:       num(m.weeklyGoalPct),
  clickup_url:           j.clickupUrl || null,
  gdrive_url:            j.gdriveUrl || null,
  news_brief_url:        m.newsBriefLink || null,
  notification_brief_url: m.notificationBriefLink || null
} }];
